claims.raw:
{
  "claims": [
    {
      "quote": "Theranos today announced that it has received the U.S. Food and Drug Administration’s clearance of its test system and test for herpes simplex 1 virus IgG.",
      "kind": "specific",
      "why": "A reader can check official FDA clearance records for the herpes simplex 1 virus IgG test."
    },
    {
      "quote": "Specifically, Theranos provided study data from 818 subjects of varying age and ethnicity, demonstrating that its system could be run accurately using only a finger stick as well as a traditional venous draw across large numbers of Theranos devices, all compared against an FDA cleared, commercially available reference method.",
      "kind": "specific",
      "why": "A third party could verify the study participant count and methodology in the FDA submission data."
    },
    {
      "quote": "Theranos’ HSV-1 studies included matrix comparison studies across sixty-nine Theranos devices.",
      "kind": "specific",
      "why": "The exact number of devices used in the matrix comparison studies can be checked against company submission records."
    },
    {
      "quote": "Theranos’ HSV-1 clinical studies also included sensitivity and specificity studies with hundreds of human samples – both capillary and venous, CDC panel testing – which demonstrated 100% agreement with the results provided by CDC, low-prevalence population tests, and other studies.",
      "kind": "specific",
      "why": "The claimed 100% agreement rate with CDC panel testing is a verifiable statistic from the study data."
    },
    {
      "quote": "Theranos is the first lab to voluntarily commit to submitting all of its LDTs to the FDA for review.",
      "kind": "specific",
      "why": "One could check whether Theranos was historically the first laboratory to make this specific voluntary commitment."
    },
    {
      "quote": "Theranos’ HSV-1 test costs $9.07 and is one of 153 tests Theranos makes available for less than $10.",
      "kind": "specific",
      "why": "A reader can check historical price lists or archived pricing data for the advertised test cost."
    },
    {
      "quote": "Theranos, Inc. is a consumer health technology company founded in 2003 by Elizabeth Holmes.",
      "kind": "specific",
      "why": "Corporate registration records and founding year can be independently verified."
    },
    {
      "quote": "The FDA’s decision provides independent validation of Theranos’ patented finger stick and venous blood testing technology and the ground breaking Theranos System upon which the HSV-1 IgG test is run",
      "kind": "vague",
      "why": "The term ground breaking is unverifiable marketing puffery used to promote their system."
    },
    {
      "quote": "FDA’s review process for 510(k) notifications is widely recognized as one of the most rigorous regulatory hurdles in the world for evaluation of the performance, accuracy, and intended use of diagnostic tests.",
      "kind": "vague",
      "why": "This subjective global comparison is an unprovable promotional assertion about regulatory difficulty."
    },
    {
      "quote": "Theranos offers lab tests in convenient locations in its Wellness Centers in Arizona and California, with plans to expand throughout the country.",
      "kind": "vague",
      "why": "The adjective convenient is a subjective assessment rather than a measurable fact."
    }
  ]
}

